package fi.hospitalos.handsfree
import org.junit.Assert.*
import org.junit.Test
class EmergencyFlowTest {
 private var now=1000L
 private val sent=mutableListOf<Pair<String,Action>>()
 private val staff=listOf(Colleague("aino","Aino",true),Colleague("ben","Ben",true))
 private val report=Isbar("65-year-old male","Cardiac arrest. CPR started immediately.","Allergy to ASA medication.","One defibrillation delivered. CPR ongoing. IV access established. No adrenaline given yet.","Join the response team in room 8.")
 private val alert=Emergency("e1","ben","8","active",1,"2026-11-14T12:00:00Z","2026-11-14T12:00:00Z","pending")
 private val patient=Patient("demo-a","Demo Patient A","enc-a","12",admissionReason="Blood-pressure observation",allergies=listOf("Penicillin — reported rash"),medications=listOf(Medication("Amlodipine","5 mg","Oral","Once daily","Dr Demo","2026-11-14T06:30:00Z")),careHistory=listOf(CareEvent("medication","Amlodipine 5 mg given orally","2026-11-14T07:10:00Z","Aino K.")))
 private fun engine()=HandsFreeEngine("aino",{now}){id,a->sent.add(id to a)}.also{it.quietMode=true;it.connection(true);it.snapshot(staff,emptyList());it.bedside.snapshot(listOf(patient),staff,null)}
 private fun show(e:HandsFreeEngine,event:Emergency=alert){e.snapshot(staff,emptyList(),emergencies=listOf(event))}
 private fun right(e:HandsFreeEngine){e.reviewDisplayed(e.card.promptId);e.physicalAccept(e.card.promptId)}
 private fun confirmPatient(e:HandsFreeEngine){e.wake();e.transcript("select patient demo-a");right(e);val id=sent.last().first;e.acknowledgement(id,true,null,null,PatientContext("demo-a","enc-a",1));e.bedside.snapshot(listOf(patient),staff,PatientContext("demo-a","enc-a",1))}
 @Test fun confirmedPatientOpensRichOverviewAndMedicationRemainsReviewed(){val e=engine();confirmPatient(e);assertTrue(e.card.title.startsWith("Patient overview"));assertTrue(e.card.body.contains("Blood-pressure"));val pages=mutableListOf(e.card.body);repeat(8){e.transcript("next");pages.add(e.card.body)};val all=pages.joinToString();assertTrue(all.contains("Penicillin"));assertTrue(all.contains("Dr Demo"));assertTrue(all.contains("Aino K."));e.transcript("Add patient note: I gave the prescribed medication at 12:00");assertEquals("review",e.card.phase);assertFalse(sent.any{it.second.type=="note.save"});right(e);assertEquals("note.save",sent.last().second.type);assertEquals("I gave the prescribed medication at 12:00",sent.last().second.fields["text"])}
 @Test fun priorityDiscardsDraftAndStaleGestureCannotSendIt(){val e=engine();e.wake();e.transcript("Message Ben please bring the belt");val old=e.card.promptId;e.reviewDisplayed(old);show(e);assertEquals("emergency-alert",e.card.phase);e.physicalAccept(old);assertTrue(sent.isEmpty());assertFalse(e.card.body.contains("cardiac arrest",true));right(e);assertEquals("emergency.acknowledge",sent.single().second.type);right(e);assertEquals(1,sent.size)}
 @Test fun failedRenderAndChangedRevisionRequireFreshVisiblePrompt(){val e=engine();show(e);e.physicalAccept(e.card.promptId);assertTrue(sent.isEmpty());val old=e.card.promptId;e.reviewDisplayed(old);show(e,alert.copy(revision=2));e.physicalAccept(old);assertTrue(sent.isEmpty());right(e);assertEquals(2,sent.single().second.fields["revision"])}
 @Test fun acknowledgementOpensExactPagedIsbarAndLeftOnlyCloses(){val e=engine();show(e);right(e);e.acknowledgement(sent.single().first,true,null,null,emergencyId="e1");show(e,alert.copy(revision=2,response="acknowledged",isbar=report));assertEquals("emergency-briefing",e.card.phase);val pages=mutableListOf(e.card.body);repeat(6){right(e);pages.add(e.card.body)};val text=pages.joinToString();assertTrue(text.contains(report.identify));assertTrue(text.contains(report.assessment));assertTrue(text.contains(report.background));now+=60000;e.tick();assertEquals("emergency-briefing",e.card.phase);e.reviewDisplayed(e.card.promptId);e.physicalBack(e.card.promptId);assertEquals("quiet",e.card.phase);assertEquals(1,sent.size);e.wake();e.transcript("show isbar");assertEquals("emergency-briefing",e.card.phase)}
 @Test fun leftDeclinesOnceWithoutResolvingEvent(){val e=engine();show(e);val p=e.card.promptId;e.reviewDisplayed(p);e.physicalBack(p);e.physicalBack(p);assertEquals("emergency.decline",sent.single().second.type);show(e,alert.copy(revision=2,response="declined"));e.acknowledgement(sent.single().first,true,null,null,emergencyId="e1");assertEquals("Response recorded",e.card.title)}
 @Test fun resolvedOrRevokedBriefingDisappearsAndCannotRespond(){for(revoked in listOf(false,true)){val e=engine();show(e,alert.copy(response="acknowledged",isbar=report));e.wake();e.transcript("show isbar");val old=e.card.promptId;e.reviewDisplayed(old);show(e,alert.copy(revision=2,status=if(revoked)"active" else "resolved",response="acknowledged",isbar=null,briefingUnavailable=revoked));assertEquals("emergency-status",e.card.phase);assertFalse(e.card.body.contains("ASA"));e.physicalAccept(old);assertTrue(sent.isEmpty())}}
 @Test fun emergencyStopsCameraWithoutSaving(){val e=engine();confirmPatient(e);e.transcript("capture reading");assertEquals("camera",e.card.phase);show(e);assertNull(e.bedside.ticket);assertNull(e.bedside.context);assertEquals("emergency-alert",e.card.phase);assertFalse(sent.any{it.second.type=="observation.save"})}
 @Test fun pendingNoteIsRetainedAndEmergencyWaitsForItsOutcome(){val e=engine();confirmPatient(e);e.transcript("save to patient records that medication given at 12:00");right(e);val note=sent.last();assertEquals("note.save",note.second.type);show(e);assertEquals(note.first,e.unresolvedCommandId);right(e);assertFalse(sent.any{it.second.type.startsWith("emergency.")});e.acknowledgement(note.first,true,null,null);assertNull(e.unresolvedCommandId);right(e);assertEquals("emergency.acknowledge",sent.last().second.type);assertEquals(1,sent.count{it.second.type=="note.save"})}
 @Test fun pendingTimeoutAllowsReceiptRecoveryBeforeEmergencyResponse(){val e=engine();e.wake();e.transcript("Message Ben please call me");right(e);val message=sent.last();show(e);now+=5001;e.tick();assertEquals(message.first,e.unresolvedCommandId);right(e);assertFalse(sent.any{it.second.type.startsWith("emergency.")});e.transcript("check outcome");assertEquals("command.status",sent.last().second.type);e.reconciled(message.first,true,null,null);right(e);assertEquals("emergency.acknowledge",sent.last().second.type);assertEquals(1,sent.count{it.second.type=="message.send"})}
 @Test fun disconnectDoesNotReplayAndCanReopenAcknowledgedBriefing(){val e=engine();show(e);right(e);val id=sent.single().first;e.connection(false);e.connection(true);show(e,alert.copy(revision=2,response="acknowledged",isbar=report));e.reconciled(id,true,null,null,"e1");assertEquals("emergency-briefing",e.card.phase);assertEquals(1,sent.count{it.second.type=="emergency.acknowledge"})}
 @Test fun receiptBeforeSnapshotCannotSendDuplicateResponse(){val e=engine();show(e);right(e);val id=sent.single().first;e.acknowledgement(id,true,null,null,emergencyId="e1");right(e);assertEquals(1,sent.size);show(e,alert.copy(revision=2,response="acknowledged",isbar=report));assertEquals("emergency-briefing",e.card.phase)}
 @Test fun lostEmergencyReceiptCanBeQueriedWithoutResubmitting(){val e=engine();show(e);right(e);val id=sent.single().first;now+=5001;e.tick();assertTrue(e.card.microphone);e.transcript("check outcome");assertEquals("command.status",sent.last().second.type);show(e,alert.copy(revision=2,response="acknowledged",isbar=report));e.reconciled(id,true,null,null,"e1");assertEquals("emergency-briefing",e.card.phase);assertEquals(1,sent.count{it.second.type=="emergency.acknowledge"})}
}
